### 回答例

以下は、文字比較回数を返し、見つかった場合は**開始位置**を返す Boyer–Moore–Horspool 法の例です。比較対象として単純な線形探索も用意し、比較回数と実行時間を確認できます。

```python
from time import perf_counter

def bm_match(text, pat):
    if not pat:
        return 0, 0

    m, n = len(pat), len(text)
    # パターン末尾以外の文字について、右端からの距離を記録
    skip = {}
    for i, c in enumerate(pat[:-1]):
        skip[c] = m - 1 - i

    comparisons = 0
    end = m - 1

    while end < n:
        j = m - 1
        while j >= 0:
            comparisons += 1
            if pat[j] != text[end - (m - 1 - j)]:
                break
            j -= 1

        if j < 0:
            return end - m + 1, comparisons

        end += skip.get(text[end], m)

    return -1, comparisons


def naive_match(text, pat):
    if not pat:
        return 0, 0

    comparisons = 0
    for start in range(len(text) - len(pat) + 1):
        for j in range(len(pat)):
            comparisons += 1
            if text[start + j] != pat[j]:
                break
        else:
            return start, comparisons

    return -1, comparisons


# パターンに含まれない文字が続くテキストでは、BMHのスキップが効きやすい
text = "x" * 100_000
pat = "abcdefghij"

for name, search in [("BMH", bm_match), ("naive", naive_match)]:
    start_time = perf_counter()
    position, comparisons = search(text, pat)
    elapsed = perf_counter() - start_time
    print(f"{name}: position={position}, comparisons={comparisons}, "
          f"time={elapsed:.6f}s")
```

