## My answer to the prompt

A reusable controlled component can filter suggestions, close the menu when there are no matches or the user selects an option, and show a red border when a supplied validator rejects the value. For large lists, it can cap the number of rendered suggestions; very large datasets may also need debouncing, an index, or virtualization.

```tsx
import { useEffect, useMemo, useRef, useState } from 'react';

type InputProps = {
  options: string[];
  value: string;
  onChange: (value: string) => void;
  validate?: (value: string) => boolean;
  placeholder?: string;
  maxSuggestions?: number;
};

export function Input({
  options,
  value,
  onChange,
  validate,
  placeholder,
  maxSuggestions = 100,
}: InputProps) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const listId = 'input-suggestions';

  const normalizedOptions = useMemo(
    () => options.map((label) => ({ label, normalized: label.toLowerCase() })),
    [options],
  );

  const matches = useMemo(() => {
    const query = value.trim().toLowerCase();
    if (!query) return [];
    return normalizedOptions
      .filter((option) => option.normalized.includes(query))
      .slice(0, maxSuggestions);
  }, [value, normalizedOptions, maxSuggestions]);

  const invalid = validate ? !validate(value) : false;
  const showMenu = open && matches.length > 0;

  useEffect(() => {
    function handleOutsidePointerDown(event: PointerEvent) {
      if (!containerRef.current?.contains(event.target as Node)) {
        setOpen(false);
        setActiveIndex(-1);
      }
    }
    document.addEventListener('pointerdown', handleOutsidePointerDown);
    return () =>
      document.removeEventListener('pointerdown', handleOutsidePointerDown);
  }, []);

  function select(label: string) {
    onChange(label);
    setOpen(false);
    setActiveIndex(-1);
  }

  return (
    <div ref={containerRef} style={{ position: 'relative', width: 300 }}>
      <input
        value={value}
        placeholder={placeholder}
        onChange={(event) => {
          onChange(event.target.value);
          setOpen(true);
          setActiveIndex(-1);
        }}
        onFocus={() => setOpen(true)}
        onKeyDown={(event) => {
          if (event.key === 'Escape') {
            setOpen(false);
            setActiveIndex(-1);
          } else if (showMenu && event.key === 'ArrowDown') {
            event.preventDefault();
            setActiveIndex((index) => (index + 1) % matches.length);
          } else if (showMenu && event.key === 'ArrowUp') {
            event.preventDefault();
            setActiveIndex((index) => (index <= 0 ? matches.length - 1 : index - 1));
          } else if (
            showMenu &&
            event.key === 'Enter' &&
            activeIndex >= 0
          ) {
            event.preventDefault();
            select(matches[activeIndex].label);
          }
        }}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={showMenu}
