Here is a component that measures whether the text wraps at the available width. If it does, the collapsed view shows one line with an ellipsis and a visible “See more” control. Tapping the control reveals the full text.

```jsx
import React, { useEffect, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

export default function ExpandableText({
  text,
  containerStyle,
  textStyle,
  seeMoreLabel = 'See more',
  seeLessLabel = 'See less',
  linkStyle,
}) {
  const [width, setWidth] = useState(0);
  const [hasOverflow, setHasOverflow] = useState(false);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setHasOverflow(false);
    setExpanded(false);
  }, [text]);

  const handleContainerLayout = (event) => {
    const nextWidth = event.nativeEvent.layout.width;
    setWidth((currentWidth) =>
      Math.abs(currentWidth - nextWidth) > 0.5 ? nextWidth : currentWidth
    );
  };

  const handleMeasure = (event) => {
    const nextHasOverflow = event.nativeEvent.lines.length > 1;
    setHasOverflow((current) =>
      current === nextHasOverflow ? current : nextHasOverflow
    );
  };

  return (
    <View style={containerStyle}>
      <View onLayout={handleContainerLayout}>
        {width > 0 && (
          <Text
            accessible={false}
            onTextLayout={handleMeasure}
            style={[
              styles.text,
              textStyle,
              styles.measurement,
              { width },
            ]}
          >
            {text}
          </Text>
        )}

        {expanded || !hasOverflow ? (
          <Text style={[styles.text, textStyle]}>{text}</Text>
        ) : (
          <View style={styles.collapsedRow}>
            <Text
              numberOfLines={1}
              ellipsizeMode="tail"
              style={[styles.text, textStyle, styles.collapsedText]}
            >
              {text}
            </Text>
            <Pressable
              accessibilityRole="button"
              onPress={() => setExpanded(true)}
              hitSlop={8}
            >
              <Text style={[styles.link, linkStyle]}>{seeMoreLabel}</Text>
            </Pressable>
          </View>
        )}

        {expanded && hasOverflow && (
          <Pressable
            accessibilityRole="button"
            onPress={() => setExpanded(false)}
            hitSlop={8}
            style={styles.seeLessButton}
          >
            <Text style={[styles.link, linkStyle]}>{seeLessLabel}</Text>
          </Pressable>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  text: {
    fontSize: 16,
    color: '#333',
  },
  measurement: {
    position: 'absolute',
    left: 0,
    top: 0,
    opacity: 0,
  },
  collapsedRow: {
    flexDirection: 'row',
    alignItems: 'baseline',
  },
