  };

  return (
    <View style={containerStyle}>
      <View onLayout={handleContainerLayout}>
        {width > 0 && (
          <Text
            accessible={false}
            onTextLayout={handleMeasure}
            style={[
              styles.text,
              textStyle,
              styles.measurement,
              { width },
            ]}
          >
            {text}
          </Text>
        )}

        {expanded || !hasOverflow ? (
          <Text style={[styles.text, textStyle]}>{text}</Text>
        ) : (
          <View style={styles.collapsedRow}>
            <Text
              numberOfLines={1}
              ellipsizeMode="tail"
              style={[styles.text, textStyle, styles.collapsedText]}
            >
              {text}
            </Text>
            <Pressable
              accessibilityRole="button"
              onPress={() => setExpanded(true)}
              hitSlop={8}
            >
              <Text style={[styles.link, linkStyle]}>{seeMoreLabel}</Text>
            </Pressable>
          </View>
        )}

        {expanded && hasOverflow && (
          <Pressable
            accessibilityRole="button"
            onPress={() => setExpanded(false)}
            hitSlop={8}
            style={styles.seeLessButton}
          >
            <Text style={[styles.link, linkStyle]}>{seeLessLabel}</Text>
          </Pressable>
        )}
      </View>
    </View>
  );
}

